import System.Exception;import System.ArgumentException;import System.ArgumentOutOfRangeException;import System.Globalization.NumberFormatInfo;import System.Type;import System.Decimal;import System.IComparable;import System.IFormattable;import System.IFormatProvider;import System.InvalidOperationException;import java.nio.file.*;import java.util.*;
class DecimalFormatStringOverloadProbe {
 interface Action{void run();}
 static String units(String s){if(s==null)return "~";StringJoiner j=new StringJoiner(",");for(char c:s.toCharArray())j.add(Integer.toString(c));return j.toString();}
 static String text(String s){if(s.equals("~"))return null;StringBuilder b=new StringBuilder();if(!s.isEmpty())for(String u:s.split(","))b.append((char)Integer.parseInt(u));return b.toString();}
 static int[] sizes(String s){if(s.equals("~"))return null;if(s.isEmpty())return new int[0];String[] p=s.split(",");int[] a=new int[p.length];for(int i=0;i<a.length;i++)a[i]=Integer.parseInt(p[i]);return a;}
 static String csv(int[] a){StringJoiner j=new StringJoiner(",");for(int v:a)j.add(Integer.toString(v));return j.toString();}
 static String outcome(Action a){try{a.run();return "OK";}catch(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),e instanceof ArgumentOutOfRangeException x&&x.get_ActualValue()!=null?x.get_ActualValue().toString():"~");}}
 static void check(String a,String e,String c){if(!a.equals(e))throw new AssertionError(c+" actual="+a+" expected="+e);}
 static String flag(boolean b){return b?"1":"0";}
 static NumberFormatInfo custom(){NumberFormatInfo n=new NumberFormatInfo();n.set_NegativeSign("~");n.set_PositiveSign("^");n.set_NumberDecimalSeparator("@");n.set_NumberGroupSeparator("_");n.set_NumberGroupSizes(new int[]{2,3});n.set_CurrencySymbol("USD");n.set_CurrencyDecimalSeparator(":");n.set_CurrencyGroupSeparator("'");n.set_CurrencyGroupSizes(new int[]{3,2});n.set_CurrencyPositivePattern(2);n.set_CurrencyNegativePattern(14);n.set_NumberNegativePattern(4);n.set_PercentSymbol("%!");return n;}
 static String compare(IComparable value,Object other){try{return "OK|"+value.CompareTo(other);}catch(Exception e){return error(e);}}
 static String format(IFormattable value,String f,IFormatProvider provider){try{return "OK|"+units(value.ToString(f,provider));}catch(Exception e){return error(e);}}
 static String error(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),"~");}
 public static void main(String[] args)throws java.lang.Exception{List<String> lines=Files.readAllLines(Path.of(args[0]));Map<Integer,int[]> bits=new HashMap<>();for(String line:lines){String[] p=line.split("\t",-1);if(p[0].equals("B"))bits.put(Integer.parseInt(p[1]),sizes(p[2]));}java.lang.reflect.Method method=Decimal.class.getDeclaredMethod("ToString",String.class);if(method.getDeclaringClass()!=Decimal.class||method.getReturnType()!=String.class||method.getParameterCount()!=1)throw new AssertionError("format-only overload shape");int cases=0,groups=1;for(String line:lines){String[] p=line.split("\t",-1);if(p[0].equals("B"))continue;Decimal value=new Decimal(bits.get(Integer.parseInt(p[1])));String f=text(p[2]),actual;try{actual="OK|"+units(value.ToString(f));}catch(Exception e){actual=error(e);}check(actual,p[3],line);check(csv(Decimal.GetBits(value)),p[4],"immutable Decimal "+line);cases++;groups+=2;}java.lang.System.out.println("PASS Decimal format-only calls="+cases+" groups="+groups);}
}
